const loadJson = (key, fallback) => { try { return JSON.parse(localStorage.getItem(key)) || fallback; } catch { return fallback; } };
const saveJson = (key, value) => { try { localStorage.setItem(key, JSON.stringify(value)); } catch (error) { console.warn("Could not persist browser preference", error); } };
let sessions = loadJson(SESSION_KEY, []), preferences = loadJson(PREF_KEY, {theme: "dark", onboardingSeen: false});
let sessionId = sessions[0]?.id || crypto.randomUUID();
const authHeaders = () => accessToken ? {Authorization: `Bearer ${accessToken}`} : {};
async function apiFetch(path, options = {}) { try { return await fetch(path, options); } catch (error) { if (window.location.origin === LOCAL_API_FALLBACK || error.name === "AbortError") throw error; return fetch(`${LOCAL_API_FALLBACK}${path}`, options); } }
async function jsonRequest(url, body, method = "POST") { const response = await apiFetch(url, {method, headers: {"Content-Type": "application/json", ...authHeaders()}, body: body == null ? undefined : JSON.stringify(body)}); const text = await response.text(); let data; try { data = text ? JSON.parse(text) : {}; } catch { data = {detail: text}; } if (!response.ok) throw new Error(data.detail || "Request failed"); return data; }
function setProgress(kind, percent, text) { $(`${kind}Progress`).style.width = `${Math.max(0, Math.min(100, percent))}%`; if (text) $(`${kind}Status`).textContent = text; }
function setHealth(text, healthy = false) { $("health").replaceChildren(); const dot = document.createElement("i"), label = document.createElement("span"); label.textContent = text; $("health").append(dot, label); $("health").classList.toggle("ok", healthy); }
function toast(message, type = "success") { const item = document.createElement("div"); item.className = `toast ${type}`; item.textContent = message; $("toastRegion").append(item); setTimeout(() => item.remove(), 4200); }
function actionDialog({title, message, confirmLabel = "Confirm", inputLabel = "", inputValue = ""}) { return new Promise(resolve => { const dialog = $("actionDialog"), inputWrap = $("actionDialogInputWrap"), input = $("actionDialogInput"); $("actionDialogTitle").textContent = title; $("actionDialogMessage").textContent = message; $("actionDialogConfirm").textContent = confirmLabel; inputWrap.hidden = !inputLabel; if (inputLabel) { inputWrap.firstChild.textContent = inputLabel; input.value = inputValue; } const finish = () => resolve(dialog.returnValue === "confirm" ? (inputLabel ? input.value.trim() : true) : null); dialog.addEventListener("close", finish, {once: true}); dialog.showModal(); if (inputLabel) setTimeout(() => input.select(), 0); }); }
function downloadJson(filename, value) { const link = document.createElement("a"), blob = new Blob([JSON.stringify(value, null, 2)], {type: "application/json"}); link.href = URL.createObjectURL(blob); link.download = filename; link.click(); URL.revokeObjectURL(link.href); }
function showIndexSummary(summary) { lastIndexSummary = summary; const stats = $("indexSummaryStats"); stats.replaceChildren(); [["Processed", summary.processed || 0], ["Changed", summary.changed_files || 0], ["Deleted", summary.deleted_files || 0], ["Skipped", summary.skipped?.length || 0], ["Chunks", summary.chunks || 0]].forEach(([label, value]) => { const item = document.createElement("div"), strong = document.createElement("strong"); strong.textContent = value; item.append(strong, label); stats.append(item); }); $("indexSummaryDetails").replaceChildren(...(summary.skipped || []).map(path => { const li = document.createElement("li"); li.textContent = `Skipped: ${path}`; return li; })); $("askChangesButton").hidden = !(summary.changed_files || summary.deleted_files); $("indexSummary").hidden = false; }
function sourceParams(path, startLine = 1, endLine = 200) { const params = new URLSearchParams({repository: activeWorkspace.repository, path, start_line: startLine, end_line: endLine, branch: activeWorkspace.branch || ""}); if (activeRepositoryId) params.set("repository_id", activeRepositoryId); return params; }
async function loadSourceText(path) { const response = await apiFetch(`/api/sources/preview?${sourceParams(path)}`, {headers: authHeaders()}), data = await response.json(); if (!response.ok) throw new Error(data.detail || `Could not open ${path}`); return {data, text: data.lines.map(line => `${String(line.number).padStart(4)}  ${line.content}`).join("\n")}; }
function fileType(path) { return path.includes(".") ? path.split(".").pop().toUpperCase() : "FILE"; }
function decorateInlineCitations(container, citations) { citations.forEach((citation, index) => { const reference = `[${citation.path}:${citation.start_line}-${citation.end_line}]`, walker = document.createTreeWalker(container, NodeFilter.SHOW_TEXT); let node; while ((node = walker.nextNode())) { const at = node.nodeValue.indexOf(reference); if (at < 0) continue; const before = document.createTextNode(node.nodeValue.slice(0, at)), after = document.createTextNode(node.nodeValue.slice(at + reference.length)), button = document.createElement("button"); button.className = "inline-citation"; button.type = "button"; button.textContent = index + 1; button.title = reference; button.onclick = () => openSource(citation); node.parentNode.replaceChild(after, node); after.before(before, button); break; } }); }

function ensureSession() { let session = sessions.find(item => item.id === sessionId); if (!session) { session = {id: sessionId, title: "New conversation", workspace: activeWorkspace?.repository || "", messages: [], updatedAt: Date.now()}; sessions.unshift(session); } return session; }
function renderConversationOptions() { const select = $("conversationSelect"), query = $("conversationSearch")?.value.trim().toLowerCase() || ""; select.replaceChildren(); [...sessions].sort((a,b) => Number(Boolean(b.favorite)) - Number(Boolean(a.favorite)) || b.updatedAt - a.updatedAt).filter(session => !query || session.title.toLowerCase().includes(query) || session.folder?.toLowerCase().includes(query) || session.tags?.some(tag => tag.toLowerCase().includes(query)) || session.messages.some(message => message.text?.toLowerCase().includes(query))).forEach(session => { const option = document.createElement("option"); option.value = session.id; option.textContent = `${session.favorite ? "★ " : ""}${session.folder ? `${session.folder} / ` : ""}${session.title}${session.tags?.length ? ` · ${session.tags.join(", ")}` : ""}`; option.selected = session.id === sessionId; select.append(option); }); renderChatMetadata(); }
function renderChatMetadata() { const session = sessions.find(item => item.id === sessionId); if (!session || !$("activeChatTags")) return; $("favoriteChatButton").textContent = session.favorite ? "★" : "☆"; $("favoriteChatButton").setAttribute("aria-pressed", String(Boolean(session.favorite))); $("activeChatTags").replaceChildren(...(session.tags || []).map(tag => { const chip = document.createElement("span"); chip.textContent = tag; return chip; })); }
function saveSessions() { sessions.forEach(session => { session.messages = session.messages.slice(-100); }); sessions = sessions.slice(0, 30); saveJson(SESSION_KEY, sessions); renderConversationOptions(); }
function newConversation() { sessionId = crypto.randomUUID(); sessions.unshift({id: sessionId, title: "New conversation", workspace: activeWorkspace?.repository || "", messages: [], updatedAt: Date.now()}); saveSessions(); renderSession(); $("question").focus(); }
function recordMessage(message) { const session = ensureSession(); session.messages.push(message); session.updatedAt = Date.now(); if (message.role === "user" && session.title === "New conversation") session.title = message.text.slice(0, 48); saveSessions(); }
function renderSession(limit = 30) { $("messages").replaceChildren(); const session = ensureSession(); renderChatMetadata(); if (!session.messages.length) return renderWelcome(); const visible = session.messages.slice(-limit); if (visible.length < session.messages.length) { const load = document.createElement("button"); load.className = "expand-message"; load.textContent = `Load ${Math.min(30, session.messages.length - visible.length)} earlier messages`; load.onclick = () => renderSession(limit + 30); $("messages").append(load); } visible.forEach(message => addMessage(message.role, message.text, message)); $("messages").scrollTop = $("messages").scrollHeight; }
function renderWelcome() { const section = document.createElement("section"); section.className = "welcome-state"; section.innerHTML = `<div class="welcome-orb"><div class="orb-ring"></div><svg viewBox="0 0 32 32"><path d="M11 10 5 16l6 6M21 10l6 6-6 6M19 5l-6 22"/></svg></div><div class="welcome-copy"><span class="welcome-label">Your private engineering copilot</span><h2>Turn complex code into<br><em>clear answers.</em></h2><p>Choose an indexed workspace, then explore architecture, behavior, and bugs with source-backed answers.</p></div><div class="suggestions"><button data-question="Explain the application architecture and how data flows between its components.">Map the architecture →</button><button data-question="Where does retrieval happen, and how are results ranked?">Trace implementation →</button><button data-question="How are errors handled and what are the main failure paths?">Investigate failures →</button></div>`; $("messages").append(section); bindSuggestions(section); }
function bindSuggestions(root = document) { root.querySelectorAll("[data-question]").forEach(button => button.onclick = () => { $("question").value = button.dataset.question; resizeComposer(); $("question").focus(); }); }

function highlightCode(code, text) { const pattern = /("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\/\/.*|#.*|\b(?:async|await|class|def|function|const|let|var|import|from|return|if|else|for|while|try|except|raise|public|private|new|true|false|null|None)\b)/g; let cursor = 0; for (const match of text.matchAll(pattern)) { code.append(document.createTextNode(text.slice(cursor, match.index))); const token = document.createElement("span"); token.textContent = match[0]; token.className = /^['"]/.test(match[0]) ? "syntax-string" : /^(\/\/|#)/.test(match[0]) ? "syntax-comment" : "syntax-keyword"; code.append(token); cursor = match.index + match[0].length; } code.append(document.createTextNode(text.slice(cursor))); }
function appendMarkdownText(container, block) { const lines = block.trim().split("\n"); let list = null; for (const line of lines) { const heading = line.match(/^(#{1,3})\s+(.+)/), bullet = line.match(/^[-*]\s+(.+)/); if (heading) { list = null; const element = document.createElement(`h${Math.min(heading[1].length + 2, 5)}`); element.textContent = heading[2]; container.append(element); } else if (bullet) { if (!list) { list = document.createElement("ul"); list.className = "answer-list"; container.append(list); } const item = document.createElement("li"); item.textContent = bullet[1]; list.append(item); } else if (line.trim()) { list = null; const p = document.createElement("p"); p.textContent = line; container.append(p); } } }
function renderAnswer(container, text) { container.replaceChildren(); text.split(/```/).forEach((block, index) => { if (index % 2) { const firstBreak = block.indexOf("\n"), language = firstBreak > -1 ? block.slice(0, firstBreak).trim() : "", codeText = firstBreak > -1 ? block.slice(firstBreak + 1) : block; const wrap = document.createElement("div"), header = document.createElement("span"), copy = document.createElement("button"), pre = document.createElement("pre"), code = document.createElement("code"); wrap.className = "code-block"; header.textContent = language || "code"; copy.type = "button"; copy.textContent = "Copy"; copy.onclick = () => navigator.clipboard.writeText(codeText); highlightCode(code, codeText.trim()); pre.append(code); wrap.append(header, copy, pre); container.append(wrap); } else if (block.trim()) appendMarkdownText(container, block); }); }
function addMessage(role, text, metadata = {}, persist = false) { document.querySelector(".welcome-state")?.remove(); const article = document.createElement("article"), avatar = document.createElement("div"), body = document.createElement("div"), content = document.createElement("div"); article.className = `message ${role}`; avatar.className = "avatar"; avatar.textContent = role === "user" ? "YOU" : "AI"; body.className = "message-body"; content.className = "message-content"; if (role === "assistant") renderAnswer(content, text); else { const p = document.createElement("p"); p.textContent = text; content.append(p); } body.append(content); article.append(avatar, body); $("messages").append(article); if (role === "assistant" && (metadata.citations || metadata.quality)) appendAnswerExtras(article, metadata, metadata.question); if (persist) recordMessage({role, text, ...metadata}); $("messages").scrollTop = $("messages").scrollHeight; return article; }
const scoreLabel = score => `${Math.round((score || 0) * 100)}%`;
function appendAnswerExtras(article, data, question) { const body = article.querySelector(".message-body"), suggestedQuestions = data.suggestedQuestions || data.suggested_questions || []; if (data.quality) { const row = document.createElement("div"); row.className = "quality-row"; [[data.quality.grounded ? "Grounded" : "Review grounding", data.quality.grounded], [`Relevant ${scoreLabel(data.quality.answer_relevance)}`, data.quality.answer_relevance >= .7], [`Citations ${scoreLabel(data.quality.citation_completeness)}`, data.quality.citation_completeness >= .8], [`${Math.round((data.quality.latency_ms || 0) / 100) / 10}s`, true]].forEach(([label, good]) => { const chip = document.createElement("span"); chip.textContent = label; chip.className = good ? "quality-good" : "quality-warn"; row.append(chip); }); body.append(row); }
  if (data.citations?.length) { decorateInlineCitations(article.querySelector(".message-content"), data.citations); const sources = document.createElement("div"); sources.className = "sources"; data.citations.slice(0, 8).forEach((citation, index) => { const button = document.createElement("button"), icon = document.createElement("span"), path = document.createElement("span"), scoreNode = document.createElement("span"), extension = citation.path.split(".").pop()?.toUpperCase().slice(0, 4) || "FILE", score = citation.score ?? citation.relevance_score; button.type = "button"; button.className = "source"; icon.className = "file-icon"; icon.textContent = `${index + 1} · ${extension}`; path.textContent = `${citation.path}:${citation.start_line}-${citation.end_line}`; button.append(icon, path); if (score != null) { scoreNode.className = "source-score"; scoreNode.textContent = scoreLabel(score); button.append(scoreNode); } button.setAttribute("aria-label", `Open source ${index + 1}: ${citation.path}, lines ${citation.start_line} to ${citation.end_line}`); button.onclick = () => openSource(citation); sources.append(button); }); body.append(sources); }
  if (data.diagnostics) { const details = document.createElement("details"), summary = document.createElement("summary"), grid = document.createElement("div"), pre = document.createElement("pre"); details.className = "generation-details"; summary.textContent = "How this answer was generated"; grid.className = "generation-grid"; [["Route", data.route || "RAG"], ["Retrieval", `${data.diagnostics.hops || 0} hops · ${data.diagnostics.retrieved_chunks || 0} chunks`], ["Grounding", data.quality?.grounded ? "Validated" : "Needs review"], ["Latency", `${Math.round((data.quality?.latency_ms || 0) / 100) / 10}s`]].forEach(([label, value]) => { const item = document.createElement("div"); item.textContent = `${label}: ${value}`; grid.append(item); }); pre.textContent = JSON.stringify({queries: data.diagnostics.queries, filters: data.diagnostics.filters, tools: data.diagnostics.tools, validation_errors: data.validation_errors || []}, null, 2); details.append(summary, grid, pre); body.append(details); }
  if (suggestedQuestions.length) { const follow = document.createElement("div"), label = document.createElement("span"); follow.className = "follow-up-questions"; label.textContent = "You could also ask"; follow.append(label); suggestedQuestions.slice(0, 3).forEach(item => { const group = document.createElement("div"), edit = document.createElement("button"), ask = document.createElement("button"); group.className = "follow-up-group"; edit.type = ask.type = "button"; edit.textContent = item; ask.textContent = "Ask"; edit.onclick = () => { $("question").value = item; resizeComposer(); $("question").focus(); }; ask.onclick = () => askQuestion(item); group.append(edit, ask); follow.append(group); }); body.append(follow); }
  const actions = document.createElement("div"); actions.className = "answer-actions"; const addAction = (label, handler) => { const button = document.createElement("button"); button.type = "button"; button.textContent = label; button.onclick = handler; actions.append(button); }; addAction("Copy", () => navigator.clipboard.writeText(article.querySelector(".message-content").innerText)); if (question) addAction("Regenerate", () => askQuestion(question)); addAction("Helpful", () => submitFeedback(1, article)); addAction("Not helpful", () => submitFeedback(-1, article)); body.append(actions); }

async function openSource(citation) { $("sourcePath").textContent = citation.path; $("sourceCode").querySelector("code").textContent = "Loading source…"; const github = activeWorkspace?.source_url?.match(/^https:\/\/github\.com\/[^/]+\/[^/]+/i)?.[0]; $("openGitHubButton").hidden = !github; if (github) $("openGitHubButton").href = `${github.replace(/\.git$/, "")}/blob/${encodeURIComponent(citation.branch || activeWorkspace?.branch || "main")}/${citation.path}#L${citation.start_line}-L${citation.end_line}`; $("sourceDrawer").showModal(); const params = new URLSearchParams({repository: activeWorkspace?.repository || $("repoName").value, path: citation.path, start_line: citation.start_line, end_line: citation.end_line, branch: citation.branch || activeWorkspace?.branch || ""}); if (activeRepositoryId) params.set("repository_id", activeRepositoryId); try { const response = await apiFetch(`/api/sources/preview?${params}`, {headers: authHeaders()}), data = await response.json(); if (!response.ok) throw new Error(data.detail); $("sourceLanguage").textContent = data.language; $("sourceMeta").textContent = `${data.branch} · lines ${data.start_line}-${data.end_line}`; const code = $("sourceCode").querySelector("code"); code.replaceChildren(); data.lines.forEach(line => { const span = document.createElement("span"); span.className = line.number >= data.highlight_start && line.number <= data.highlight_end ? "source-line highlighted" : "source-line"; span.textContent = `${String(line.number).padStart(4)}  ${line.content}\n`; code.append(span); }); } catch (error) { $("sourceCode").querySelector("code").textContent = `Could not load source: ${error.message}`; } }
async function hashText(text) { const bytes = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text)); return [...new Uint8Array(bytes)].map(value => value.toString(16).padStart(2, "0")).join(""); }
async function submitFeedback(rating, article) { const answer = article.querySelector(".message-content").innerText, comment = rating < 0 ? await actionDialog({title: "Help improve this answer", message: "What was missing or incorrect? This is optional.", confirmLabel: "Send feedback", inputLabel: "Feedback"}) : ""; if (comment === null) return; try { await jsonRequest("/api/feedback", {session_id: sessionId, repository: activeWorkspace?.repository || $("repoName").value, repository_id: activeRepositoryId, rating, comment, answer_sha256: await hashText(answer)}); article.querySelector(".answer-actions").dataset.feedback = "Thanks for your feedback"; toast("Feedback saved"); } catch (error) { toast(error.message, "error"); } }

async function pollJob(statusUrl, kind) { for (;;) { await new Promise(resolve => setTimeout(resolve, 750)); const response = await apiFetch(statusUrl, {headers: authHeaders()}), data = await response.json(); if (!response.ok) throw new Error(data.detail || "Could not read indexing progress"); setProgress(kind, data.progress || 0, `${data.progress || 0}% · ${data.message}`); if (data.status === "complete") return data; if (data.status === "failed") throw new Error(data.message); } }
async function runIndex() { const source = $("repoPath").value.trim(), github = /^https:\/\/github\.com\//i.test(source); $("indexButton").disabled = true; $("retryIndexButton").hidden = true; setProgress("index", 8, github ? "Cloning public repository…" : "Reading source files…"); try { let result = {}; if (authEnabled) { if (!activeRepositoryId) throw new Error("Select a registered repository"); const job = await jsonRequest(`/api/repositories/${activeRepositoryId}/index`, {}), completed = await pollJob(`/api/index-jobs/${job.id}`, "index"); result = completed.result || {}; } else { const data = await jsonRequest(github ? "/api/github/index" : "/api/index", github ? {url: source, repository_name: $("repoName").value || null} : {repository_path: source, repository_name: $("repoName").value}), completed = data.status_url ? await pollJob(data.status_url, "index") : {result: data}; result = completed.result || data; $("repoName").value = result.repository; if (github && result.repository) { preferences.sourceUrls = {...(preferences.sourceUrls || {}), [result.repository]: source}; saveJson(PREF_KEY, preferences); } setProgress("index", 100, `${result.files || 0} files · ${result.chunks || 0} chunks · ${result.branch || "ready"}`); } showIndexSummary({processed: result.files, chunks: result.chunks, skipped: [], changed_files: result.changed_files, deleted_files: result.deleted_files}); toast("Repository indexed successfully"); await loadWorkspaces(); } catch (error) { setProgress("index", 0, error.message); $("retryIndexButton").hidden = false; toast(error.message, "error"); } finally { $("indexButton").disabled = false; } }
function selectedUploads() { const items = [...Array.from($("fileUpload").files || []).map(file => ({file, path: file.name})), ...Array.from($("folderUpload").files || []).map(file => ({file, path: file.webkitRelativePath || file.name})), ...pickedFolderFiles], seen = new Set(); return items.filter(item => !excludedUploadPaths.has(item.path) && !seen.has(item.path) && seen.add(item.path)); }
async function runUpload() { const selected = selectedUploads(); if (!selected.length) { toast("Select at least one file", "error"); return; } $("uploadButton").disabled = true; setProgress("upload", 5, "Checking selected files…"); try { const readable = [], unreadable = []; for (const item of selected) try { await item.file.slice(0, 1024).arrayBuffer(); readable.push(item); } catch { unreadable.push(item.path); } if (!readable.length) throw new Error("The browser could not read these files. Choose a local folder and avoid cloud-only files or broken links."); const form = new FormData(); readable.forEach(item => form.append("files", item.file, item.path)); form.append("repository", $("repoName").value); if (activeRepositoryId) form.append("repository_id", activeRepositoryId); setProgress("upload", 18, `Uploading ${readable.length} files…`); const response = await apiFetch("/api/uploads", {method: "POST", headers: authHeaders(), body: form}), data = await response.json(); if (!response.ok) throw new Error(data.detail || "Upload failed"); const completed = data.status_url ? await pollJob(data.status_url, "upload") : {}; setProgress("upload", 100, `${data.files.length} files indexed${data.skipped?.length ? ` · ${data.skipped.length} skipped` : ""}`); showIndexSummary({processed: data.files.length, chunks: completed.result?.chunks || 0, skipped: [...(data.skipped || []), ...unreadable]}); $("fileUpload").value = $("folderUpload").value = ""; pickedFolderFiles = []; excludedUploadPaths.clear(); updateFileCount(); toast("Documents indexed successfully"); await loadWorkspaces(); } catch (error) { setProgress("upload", 0, error.message); toast(error.message, "error"); } finally { $("uploadButton").disabled = false; } }

async function loadWorkspaces() { let entries; if (authEnabled) entries = await apiFetch("/api/repositories", {headers: authHeaders()}).then(response => response.json()).then(items => items.map(item => ({id: item.id, repository: item.name, branch: item.default_branch, chunks: 0, file_count: 0, active_version: item.active_version, managed: true}))); else entries = await apiFetch("/api/local-sources", {headers: authHeaders()}).then(response => response.json()); entries = entries.map(item => ({...item, source_url: item.source_url || preferences.sourceUrls?.[item.repository]})); workspaces = entries; const select = $("workspaceSelect"); select.replaceChildren(); if (!entries.length) { const option = document.createElement("option"); option.textContent = "No indexed workspace"; option.value = ""; select.append(option); activeWorkspace = null; updateWorkspaceUI(); return; } entries.forEach((item, index) => { const option = document.createElement("option"); option.value = item.id; option.textContent = `${item.repository} · ${item.branch}`; select.append(option); if ((preferences.workspace === item.id) || (!preferences.workspace && index === 0)) option.selected = true; }); selectWorkspace(select.value); }
function selectWorkspace(id) { activeWorkspace = workspaces.find(item => item.id === id) || null; activeRepositoryId = activeWorkspace?.managed ? activeWorkspace.id : null; if (activeWorkspace) { $("repoName").value = activeWorkspace.repository; preferences.workspace = id; saveJson(PREF_KEY, preferences); } updateWorkspaceUI(); }
function updateWorkspaceUI() { const item = activeWorkspace, ready = Boolean(item); $("activeContext").textContent = item ? `${item.repository} · ${item.branch}${item.active_version ? ` · index v${item.active_version}` : ""}` : "No workspace selected"; $("workspaceMeta").textContent = item ? `${item.file_count || 0} files · ${item.chunks || 0} chunks${item.expires_at ? ` · expires ${new Date(item.expires_at).toLocaleString()}` : ""}` : "Select or index a knowledge source"; $("removeWorkspaceButton").hidden = !item?.temporary; $("workspaceGate").hidden = ready; $("question").disabled = !ready; $("chatForm").classList.toggle("is-disabled", !ready); $("chatForm").querySelector("button[type='submit']").disabled = !ready; const files = item?.files || []; $("uploadedFiles").replaceChildren(); files.forEach(name => { const li = document.createElement("li"); li.textContent = name; $("uploadedFiles").append(li); }); $("uploadedFileTotal").textContent = files.length; $("uploadedFilesPanel").hidden = !files.length; }

function createStreamProgress(body) { const row = document.createElement("div"); row.className = "stream-steps"; ["Planning", "Retrieving", "Reranking", "Generating", "Validating"].forEach(label => { const chip = document.createElement("span"); chip.className = "stream-step"; chip.textContent = label; row.append(chip); }); body.prepend(row); return row; }
function updateStreamProgress(row, status) { const value = status.toLowerCase(), stages = [...row.children]; let active = value.includes("classif") || value.includes("planning") ? 0 : value.includes("search") || value.includes("retriev") ? 1 : value.includes("rerank") || value.includes("expand") ? 2 : value.includes("generat") ? 3 : value.includes("validat") ? 4 : 0; stages.forEach((stage, index) => { stage.classList.toggle("done", index < active); stage.classList.toggle("active", index === active); }); }

