async function initializeAuthentication() { const config = await apiFetch("/api/auth/config").then(response => response.json()); if (!config.enabled) return; authEnabled = true; const issuer = new URL(config.issuer), realm = issuer.pathname.split("/").pop(); await new Promise((resolve, reject) => { const script = document.createElement("script"); script.src = `${issuer.origin}/js/keycloak.js`; script.onload = resolve; script.onerror = reject; document.head.append(script); }); const keycloak = new Keycloak({url: issuer.origin, realm, clientId: config.client_id}); await keycloak.init({onLoad: "login-required", pkceMethod: "S256"}); accessToken = keycloak.token; $("repoPath").value = "Managed by administrator"; $("repoPath").disabled = true; setInterval(async () => { if (await keycloak.updateToken(60)) accessToken = keycloak.token; }, 30000); }

