function updateFileCount() { const files = selectedUploads(), folder = files[0]?.path.split("/")[0], total = files.reduce((sum, item) => sum + item.file.size, 0), review = $("uploadReview"); $("fileCount").textContent = files.length ? `${files.length} selected · ${(total / 1024 / 1024).toFixed(1)} MB${folder ? ` · ${folder}` : ""}` : "PDF, DOCX, code and text"; review.replaceChildren(); files.slice(0, 100).forEach(item => { const row = document.createElement("div"), name = document.createElement("span"), remove = document.createElement("button"); row.className = "upload-review-item"; name.textContent = `${item.path} · ${(item.file.size / 1024).toFixed(1)} KB`; remove.type = "button"; remove.textContent = "Remove"; remove.setAttribute("aria-label", `Remove ${item.path}`); remove.onclick = () => { excludedUploadPaths.add(item.path); updateFileCount(); }; row.append(name, remove); review.append(row); }); review.hidden = !files.length; $("uploadStatus").textContent = files.length ? `${files.length} unique files ready; review or remove files before indexing.` : "Files stay private and are processed locally."; }
